package fr.romitou.mongosk;

import com.mongodb.MongoTimeoutException;
import org.junit.jupiter.api.Test;
import org.reactivestreams.Publisher;
import org.reactivestreams.Subscriber;
import org.reactivestreams.Subscription;

import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.jupiter.api.Assertions.*;

class MongoRequestTest {

    private static final long LONG_TIMEOUT = 5000;

    /**
     * A publisher which keeps its subscriber, to emit its signals later like the driver does.
     */
    private static final class ManualPublisher implements Publisher<String> {
        private final AtomicReference<Subscriber<? super String>> subscriber = new AtomicReference<>();
        private final AtomicBoolean cancelled = new AtomicBoolean();

        @Override
        public void subscribe(Subscriber<? super String> s) {
            subscriber.set(s);
            s.onSubscribe(new Subscription() {
                @Override
                public void request(long n) {
                }

                @Override
                public void cancel() {
                    cancelled.set(true);
                }
            });
        }
    }

    @Test
    void doesNotCompleteBeforeTheResponseIsReceived() {
        ManualPublisher publisher = new ManualPublisher();
        var response = MongoRequest.send(publisher, LONG_TIMEOUT);
        assertFalse(response.isDone());

        publisher.subscriber.get().onNext("a");
        assertFalse(response.isDone());

        publisher.subscriber.get().onNext("b");
        publisher.subscriber.get().onComplete();
        assertEquals(List.of("a", "b"), response.join().results());
        assertNull(response.join().error());
    }

    @Test
    void holdsTheErrorOfTheDriver() {
        ManualPublisher publisher = new ManualPublisher();
        var response = MongoRequest.send(publisher, LONG_TIMEOUT);

        IllegalStateException error = new IllegalStateException("failed");
        publisher.subscriber.get().onError(error);

        assertSame(error, response.join().error());
        assertTrue(response.join().results().isEmpty());
    }

    @Test
    void holdsTheErrorOfAPublisherFailingOnSubscription() {
        IllegalStateException error = new IllegalStateException("closed");
        Publisher<String> publisher = subscriber -> {
            throw error;
        };

        assertSame(error, MongoRequest.send(publisher, LONG_TIMEOUT).join().error());
    }

    @Test
    void cancelsTheRequestWhenTheTimeoutIsReached() {
        ManualPublisher publisher = new ManualPublisher();
        var response = MongoRequest.<String>send(publisher, 20).join();

        assertInstanceOf(MongoTimeoutException.class, response.error());
        assertTrue(publisher.cancelled.get());
    }

    @Test
    void waitsForThePendingRequests() throws InterruptedException {
        ManualPublisher publisher = new ManualPublisher();
        var response = MongoRequest.send(publisher, LONG_TIMEOUT);

        Thread waiting = new Thread(MongoRequest::awaitPending);
        waiting.start();
        waiting.join(50);
        assertTrue(waiting.isAlive());

        publisher.subscriber.get().onComplete();
        waiting.join(LONG_TIMEOUT);
        assertFalse(waiting.isAlive());
        assertTrue(response.isDone());
    }
}
